 Dictionary<string,List<BackupDemand>> SourcesByItem(List<BackupDemand> demands,out List<BackupDemand> unmapped){var result=new Dictionary<string,List<BackupDemand>>();unmapped=new List<BackupDemand>();var targets=backupBill.Select(b=>b.Target).ToList();foreach(var d in demands){string slot;BackupTarget target;if(d.TargetSlotId!=null)target=targets.SingleOrDefault(t=>t.SlotId==d.TargetSlotId&&BackupMapping.Identity(t)==d.TargetIdentity);else if(backupBillRoutes.TryGetValue(d.Key,out slot))target=targets.FirstOrDefault(t=>t.SlotId==slot);else target=BackupMapping.Suggest(d,targets);if(target==null){if(d.Quantity>1e-10||d.ManualOverride)unmapped.Add(d);continue;}List<BackupDemand> rows;if(!result.TryGetValue(target.SlotId,out rows)){rows=new List<BackupDemand>();result[target.SlotId]=rows;}rows.Add(d);}return result;}
 void AddUnmappedBoqRows(IEnumerable<BackupDemand> items){var rows=items.Where(q=>!q.ManualOverride).ToList();if(rows.Count==0)return;int section=boqGrid.Rows.Add("","COMPUTED QUANTITIES — SELECT BACKUP PAY ITEM ONCE","","");boqGrid.Rows[section].ReadOnly=true;boqGrid.Rows[section].DefaultCellStyle.BackColor=PremiumControls.AccentSoft;foreach(var q in rows){int n=boqGrid.Rows.Add("",q.Description,q.Quantity.ToString("0.########",CultureInfo.InvariantCulture),q.Unit);boqGrid.Rows[n].ReadOnly=true;string branch="unmapped:"+q.Key;boqGrid.Rows[n].Cells[1].ToolTipText="Computed quantity is retained in Tool Kit. Use Map BACKUP items for an ambiguous/new specification; the app does not guess among duplicate pay items.";foreach(var source in q.Sources){var detail=new DataGridViewRow();detail.CreateCells(boqGrid,"","    "+source.Description,source.Quantity.ToString("0.########",CultureInfo.InvariantCulture),source.Unit);detail.ReadOnly=true;detail.DefaultCellStyle.ForeColor=PowTheme.Muted;BoqDisclosure.Parent(boqGrid.Rows[n],branch);BoqDisclosure.Detail(detail,branch);boqGrid.Rows.Add(detail);}}}
 void UpdateBackupBillDashboard(){var selected=boqGrid.CurrentRow==null?null:boqGrid.CurrentRow.Tag as BackupBillItem;string selectedId=selected==null?null:selected.Slot;var scroll=BoqScrollState.Capture(boqGrid);bool selectedVisible=boqGrid.CurrentRow!=null&&boqGrid.CurrentRow.Displayed;paintingBackupBill=true;var rowSizing=boqGrid.AutoSizeRowsMode;boqGrid.SuspendLayout();boqGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.None;try{boqGrid.Rows.Clear();var pendingRows=new List<DataGridViewRow>();bool blankCatalogue=!HasMeasuredInputs()&&backupBill.All(b=>!b.ManualQuantity.HasValue&&!b.WorkbookQuantity.HasValue)&&!ManualBoqQuantities().Any();var demands=(blankCatalogue?new List<BackupDemand>():BackupQuantities(false)).Where(d=>d.Quantity>1e-10||d.ManualOverride||d.Sources.Any(s=>s.Quantity>1e-10)||backupBillRoutes.ContainsKey(d.Key)).ToList();List<BackupDemand> unmapped;var grouped=SourcesByItem(demands,out unmapped);foreach(var item in backupBill){List<BackupDemand> sources;if(!grouped.TryGetValue(item.Slot,out sources))sources=new List<BackupDemand>();var matching=sources.Where(d=>BackupMapping.Unit(d.Unit)==BackupMapping.Unit(item.Unit)).ToList();bool computed=matching.Count>0&&BackupMapping.Unit(item.Unit)!="ls";double? quantity=item.ManualQuantity??(computed||matching.Any(d=>d.ManualPriority>=1)?(double?)BackupMapping.FinalQuantity(matching,item.Unit):item.WorkbookQuantity);var row=new DataGridViewRow();row.CreateCells(boqGrid,item.Code,item.Description,item.ManualInputText??(quantity.HasValue?quantity.Value.ToString("0.########",CultureInfo.InvariantCulture):""),item.Unit);pendingRows.Add(row);row.Tag=item;string branch="item:"+item.Slot+":"+item.Signature;foreach(DataGridViewCell cell in row.Cells)cell.ReadOnly=true;row.Cells[2].ReadOnly=computed&&!item.ManualQuantity.HasValue&&item.ManualInputText==null;row.Cells[2].Style.BackColor=row.Cells[2].ReadOnly?ModernUi.Soft:ModernUi.Input;row.Cells[2].ToolTipText=computed?"Computed from Tool Kit measurements.":"Enter manual quantity here; 1 LS is never inferred. Zero clears quantity; blank removes the override.";foreach(var d in sources)foreach(var source in d.Sources){var detail=new DataGridViewRow();detail.CreateCells(boqGrid,"","    "+source.Description,source.Quantity.ToString("0.########",CultureInfo.InvariantCulture),source.Unit);detail.ReadOnly=true;detail.DefaultCellStyle.ForeColor=PowTheme.Muted;BoqDisclosure.Parent(row,branch);BoqDisclosure.Detail(detail,branch);pendingRows.Add(detail);}}
 boqGrid.Rows.AddRange(pendingRows.ToArray());AddUnmappedBoqRows(unmapped);AddLegacyBoqRows();if(boqDisclosure!=null)boqDisclosure.Apply();var issues=WorksValidationIssues();boqStatus.ForeColor=issues.Count>0?Color.Firebrick:PowTheme.Teal;boqStatus.Text=backupBill.Count+" BACKUP pay items | computed quantities update here immediately"+(unmapped.Count>0?" | "+unmapped.Count+" source(s) need one-time mapping":"")+(issues.Count>0?" | Partial output; input issues are listed":"");}finally{boqGrid.AutoSizeRowsMode=rowSizing;boqGrid.ResumeLayout();paintingBackupBill=false;if(selectedId!=null&&selectedVisible){var row=boqGrid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>r.Tag is BackupBillItem&&((BackupBillItem)r.Tag).Slot==selectedId);if(row!=null)boqGrid.CurrentCell=row.Cells[2];}scroll.Restore(boqGrid);}}
 void AddLegacyBoqRows(){if(plumbingLs==null)return;foreach(DataGridViewRow item in plumbingLs.Rows){if(item.IsNewRow||Cell(item,6)!=""||Cell(item,2)=="")continue;int n=boqGrid.Rows.Add("",Cell(item,2),Cell(item,3),Cell(item,5));var row=boqGrid.Rows[n];row.Tag=item;foreach(DataGridViewCell cell in row.Cells)cell.ReadOnly=true;row.Cells[2].ReadOnly=false;row.Cells[2].Style.BackColor=ModernUi.Input;}}
}
